What will be the output of this code, if the user enters Chef?

```csharp
using System;

namespace MyApplication
{
    class Program
    {
        static void Main(string[] args)
        {
            string s = Console.ReadLine();
            Console.Write("Your name is: " + s);
        }
    }
}
```

What will be the output of this code, if the a = 5 and b = 9 based on user input?

```csharp
using System;

namespace MyApplication
{
    class Program
    {
        static void Main(string[] args)
        {
            int a = Convert.ToInt32(Console.ReadLine());
            int b = Convert.ToInt32(Console.ReadLine());
            Console.Write(a + "" + b + "" + (a + b));
        }
    }
}
```

What will be the output of this code, if the user enters 5 and 9?

```csharp
using System;

namespace MyApplication
{
    class Program
    {
        static void Main(string[] args)
        {
            int a = Convert.ToInt32(Console.ReadLine());
            int b = Convert.ToInt32(Console.ReadLine());
            int c = a + 2;
            int d = c + b;
            Console.Write(d);
        }
    }
}
```

